-- Replace the beginner straddle steps ("Straddle från grunden", added in 022) with
-- research-based exercises: frog stretch, adductor slides, straddle good mornings and the elevated pancake.
-- Generated by scripts/straddle-base-migration.mjs from src/skills.js; edit those, not the .sql.
-- Same exercise ids as 022, only their metadata changes. Saved workouts, XP, ranks, skill levels and baselines are unchanged.
begin;
alter function public.arc_strength_meta(text) rename to arc_strength_meta_v23;
create function public.arc_strength_meta(id text) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select coalesce((select value from jsonb_array_elements('[{"id":"sk-straddle-base-1","name":"Grodan","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[45,90,135,180,225,270],"cue":"På underarmar och knän, knäna brett och i linje med höften. Smalbenen parallella, fotlederna i linje med knäna. Pressa knäna mot golvet 5 s på halv kraft, slappna av 20 s och glid lite bredare. Mål: 3 × 45 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":1,"skillAnim":"frog-stretch","skillSets":3,"skillAmount":45},{"id":"sk-straddle-base-2","name":"Adduktorglid","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"reps","thresholds":[8,16,24,32,40,48],"cue":"Strumpor på ett halt golv, händerna på höften. Låt fötterna glida isär med raka ben, bara så långt du har kontroll. Dra ihop benen med insidan av låren. Mål: 3 × 8. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":2,"skillAnim":"adductor-slide","skillSets":3,"skillAmount":8},{"id":"sk-straddle-base-3","name":"Bredbent good morning","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"reps","thresholds":[8,16,24,32,40,48],"cue":"Fötterna brett, knäna lätt böjda och pressade utåt. Fäll från höften med platt rygg, bröstet först. Res dig med säte och baksida lår. Mål: 3 × 8, 2 s i botten. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":3,"skillAnim":"straddle-good-morning","skillSets":3,"skillAmount":8},{"id":"sk-straddle-base-4","name":"Upphöjd pancake good morning","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"reps","thresholds":[8,16,24,32,40,48],"cue":"Sitt på en kudde eller ett block, benen brett och tårna mot taket. Fäll framåt med lång rygg, håll 2 s. Res dig med höften och ryggen, inte med armarna. Mål: 3 × 8, 2 s i botten. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":4,"skillAnim":"elevated-pancake-gm","skillSets":3,"skillAmount":8},{"id":"sk-straddle-base-5","name":"Upphöjd pancake, kontrakt-slapp","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Sitt upphöjt, benen brett, knäna får vara lätt böjda. Pressa hälarna mot golvet 5 s, slappna av och fäll lite längre. Stanna och andas i det nya läget. Mål: 3 × 30 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":5,"skillAnim":"elevated-pancake","skillSets":3,"skillAmount":30}]'::jsonb) where value->>'id'=id), public.arc_strength_meta_v23(id))
$$;
revoke all on function public.arc_strength_meta_v23(text) from public,anon,authenticated;
create or replace function public.training_expansion_ready() returns integer language sql stable as $$select 24$$;
notify pgrst,'reload schema';
commit;
